def minimum_and_maximum(values):
    return min(values), max(values)

lowest, highest = minimum_and_maximum([7, 2, 9])
print(lowest, highest)  # 2 9

scores = {"Amy": 91, "Bo": 84}
print(scores.get("Chen", 0))
for name, score in scores.items():
    print(name, score)

words = ["red", "blue", "red", "green"]
counts = {}
for word in words:
    counts[word] = counts.get(word, 0) + 1
print(counts)

